const headers = $json.headers || {};
const expectedSecret = $env.TELEGRAM_WEBHOOK_SECRET || '';
const providedSecret = headers['x-telegram-bot-api-secret-token'] || headers['X-Telegram-Bot-Api-Secret-Token'] || '';
if (!expectedSecret || providedSecret !== expectedSecret) {
  throw new Error('Unauthorized Telegram webhook request');
}

const body = $json.body || $json;
const msg = body.message || body.edited_message || {};
const updateId = body.update_id ?? '';
const text = (msg.text || msg.caption || '').trim();
const chatId = msg.chat?.id || msg.from?.id || '';
const firstName = msg.from?.first_name || msg.chat?.first_name || '';
const command = text.split(/\s+/)[0].toLowerCase();

const urlMatch = text.match(/https?:\/\/\S+/);
const url = urlMatch ? urlMatch[0].replace(/[)>\]}.,]+$/, '') : '';
let platform = 'unsupported';

try {
  const parsed = new URL(url);
  const host = parsed.hostname.toLowerCase().replace(/\.$/, '');
  const matches = (base) => host === base || host.endsWith(`.${base}`);
  if (!parsed.username && !parsed.password && !parsed.port && ['http:', 'https:'].includes(parsed.protocol)) {
    if (matches('tiktok.com')) platform = 'TikTok';
    else if (matches('instagram.com')) platform = 'Instagram';
    else if (matches('x.com') || matches('twitter.com')) platform = 'X/Twitter';
    else if (matches('facebook.com') || host === 'fb.watch') platform = 'Facebook';
  }
} catch {
  platform = 'unsupported';
}

const isStart = command === '/start';

return [{
  json: {
    raw: text,
    url,
    platform,
    supported: !!url && platform !== 'unsupported',
    is_start: isStart,
    command,
    chat_id: String(chatId),
    first_name: firstName,
    request_id: updateId === '' ? undefined : String(updateId)
  }
}];
